&lt;th&gt;Monthly&lt;/th&gt;
&lt;th&gt;Per credit&lt;/th&gt;
&lt;th&gt;Annual (per month)&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;100&lt;/td&gt;
&lt;td&gt;$25&lt;/td&gt;
